const fs = require('fs');
const path = require('path');
const vm = require('vm');

const srcDir = process.argv[2];
const html = fs.readFileSync(path.join(srcDir, 'index.html'), 'utf8');
const scripts = [...html.matchAll(/<script\s+src="([^"]+)"/g)].map((m) => m[1]);

class ClassList {
  constructor() { this.values = new Set(); }
  toggle(name, force) { force ? this.values.add(name) : this.values.delete(name); }
  contains(name) { return this.values.has(name); }
}
class Element {
  constructor(id) {
    this.id = id; this.textContent = ''; this.hidden = true;
    this.style = {}; this.attrs = {}; this.classList = new ClassList();
    this.parentElement = null;
  }
  setAttribute(name, value) { this.attrs[name] = String(value); }
  getAttribute(name) { return this.attrs[name]; }
}
const ids = ['game', 'shells', 'tide', 'tide-status', 'tide-bar', 'tide-track', 'result', 'hud'];
const elements = Object.fromEntries(ids.map((id) => [id, new Element(id)]));
elements['tide-bar'].parentElement = elements['tide-track'];
elements.game.width = 480; elements.game.height = 320;
elements.game.getContext = () => ({ clearRect() {}, fillRect() {}, beginPath() {}, arc() {}, fill() {} });

let nextFrame = null;
let settleCalls = 0;
const context = {
  console, Math,
  document: { getElementById: (id) => elements[id] },
  window: { addEventListener() {} },
  performance: { now: () => 0 },
  requestAnimationFrame: (callback) => { nextFrame = callback; },
  clearInterval() {},
};
vm.createContext(context);
for (const script of scripts) {
  vm.runInContext(fs.readFileSync(path.join(srcDir, script), 'utf8'), context, { filename: script });
}
vm.runInContext('const originalSettleRound = settleRound; settleRound = () => { settleCalls += 1; return originalSettleRound(); };', vm.createContext({}));

function state() {
  return vm.runInContext(`({remainingSeconds, roundState, shellCount, shells: shells.length,
    player: {x: player.x, y: player.y}, urgent: hudElement.classList.contains("urgent"),
    status: tideStatusElement.textContent, result: resultElement.textContent})`, context);
}
function check(condition, message) { if (!condition) throw new Error(message); }

const initial = state();
check(scripts.join(',') === 'main.js', `script order=${scripts.join(',')}`);
check(initial.remainingSeconds === 60 && elements.tide.textContent === '60', 'initial countdown is not 60');
check(elements['tide-bar'].style.width === '100%', 'initial bar is not 100%');
check(elements['tide-track'].getAttribute('aria-valuenow') === '60', 'initial aria-valuenow is not 60');
console.log(`PASS initial: scripts=${scripts.join(',')}, remaining=${initial.remainingSeconds}, tide=${elements.tide.textContent}, bar=${elements['tide-bar'].style.width}, aria=${elements['tide-track'].getAttribute('aria-valuenow')}, shells=${initial.shells}`);

vm.runInContext('remainingSeconds = 10.05; update(0.05);', context);
const urgent = state();
check(urgent.remainingSeconds === 10 && urgent.urgent && urgent.status === '即将涨潮！', `urgent boundary failed: ${JSON.stringify(urgent)}`);
console.log(`PASS urgent: remaining=${urgent.remainingSeconds}, urgent=${urgent.urgent}, status=${urgent.status}, tide=${elements.tide.textContent}`);

vm.runInContext('shellCount = 4; shellCountElement.textContent = "4"; remainingSeconds = 0.01; update(0.02);', context);
const settled = state();
